def chamber_of_secrets(arr: list[int], x: int) -> list[int]:
    from collections import deque
    q = deque([(val, i + 1) for i, val in enumerate(arr)])
    chosen = []
    for _ in range(x):
        if not q:
            break
        popped = []
        for _ in range(min(x, len(q))):
            popped.append(q.popleft())
        # pick max val; if tie, earliest
        max_val = max(p[0] for p in popped)
        selected = None
        for p in popped:
            if p[0] == max_val and selected is None:
                selected = p
                chosen.append(p[1])
            else:
                q.append((max(0, p[0] - 1), p[1]))
    return chosen
